            if (Objects.WindowBoundsStore.TryGet("VisualizeNetwork", out double w, out double h))
                Size = new System.Drawing.Size((int)w, (int)h);
            FormClosing += (s, e) => Objects.WindowBoundsStore.Save("VisualizeNetwork", Width, Height);
        }

